import React, { useState, useEffect } from "react";
import {
  Container,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
} from "@mui/material";
import dayjs from "dayjs";

const REACT_APP_SHEET_ID = process.env.REACT_APP_SHEET_ID;
const REACT_APP_API_KEY = process.env.REACT_APP_API_KEY;
const REACT_APP_SHEET_NAME = process.env.REACT_APP_SHEET_NAME;
const SHEET_API_URL = `https://sheets.googleapis.com/v4/spreadsheets/${REACT_APP_SHEET_ID}/values/${REACT_APP_SHEET_NAME}?key=${REACT_APP_API_KEY}`;

const getDateRange = (filter) => {
  const today = dayjs().format("YYYY-MM-DD");
  const tomorrow = dayjs().add(1, "day").format("YYYY-MM-DD");
  const startOfWeek = dayjs().startOf("week").add(1, "day").format("YYYY-MM-DD"); // 이번주 월요일
  const endOfWeek = dayjs().startOf("week").add(6, "day").format("YYYY-MM-DD"); // 이번주 토요일
  const startOfNextWeek = dayjs().startOf("week").add(8, "day").format("YYYY-MM-DD"); // 다음주 월요일
  const endOfNextWeek = dayjs().startOf("week").add(13, "day").format("YYYY-MM-DD"); // 다음주 토요일

  switch (filter) {
    case "today":
      return [today];
    case "tomorrow":
      return [tomorrow];
    case "thisWeek":
      return Array.from({ length: 6 }, (_, i) => dayjs(startOfWeek).add(i, "day").format("YYYY-MM-DD"));
    case "nextWeek":
      return Array.from({ length: 6 }, (_, i) => dayjs(startOfNextWeek).add(i, "day").format("YYYY-MM-DD"));
    default:
      return [];
  }
};

const OrderList = () => {
  const [filter, setFilter] = useState("all");
  const [sortAsc, setSortAsc] = useState(true);
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const response = await fetch(SHEET_API_URL);
        const result = await response.json();

        if (result.values) {
          const [headers, ...rows] = result.values;
          const formattedOrders = rows.map((row, index) => ({
            id: index + 1,
            company: row[1] || "", // 업체명
            content: row[4] || "", // 발주 내용
            deliveryDate: dayjs(row[3]).format("YYYY-MM-DD") || "", // 배송일 변환
            remark: row[5] || "", // 비고
          }));
          setOrders(formattedOrders);
        }
      } catch (error) {
        console.error("Error fetching orders:", error);
      }
    };
    fetchOrders();
  }, []);

  const filteredOrders =
    filter === "all"
      ? orders
      : orders.filter((order) => getDateRange(filter).includes(order.deliveryDate));

  const sortedOrders = [...filteredOrders].sort((a, b) =>
    sortAsc ? a.deliveryDate.localeCompare(b.deliveryDate) : b.deliveryDate.localeCompare(a.deliveryDate)
  );

  return (
    <Container maxWidth="md" sx={{ mt: 3 }}>
      <div style={{ display: "flex", gap: "8px", marginBottom: "16px" }}>
        {[
          { label: "전체", value: "all" },
          { label: "오늘", value: "today" },
          { label: "내일", value: "tomorrow" },
          { label: "이번 주", value: "thisWeek" },
          { label: "다음 주", value: "nextWeek" },
        ].map((btn) => (
          <Button
            key={btn.value}
            variant={filter === btn.value ? "contained" : "outlined"}
            onClick={() => setFilter(btn.value)}
          >
            {btn.label}
          </Button>
        ))}
      </div>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>업체명</TableCell>
              <TableCell>발주 내용</TableCell>
              <TableCell
                style={{ cursor: "pointer" }}
                onClick={() => setSortAsc(!sortAsc)}
              >
                배송일 {sortAsc ? "▲" : "▼"}
              </TableCell>
              <TableCell>비고</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {sortedOrders.map((order) => (
              <TableRow key={order.id}>
                <TableCell>{order.company}</TableCell>
                <TableCell>{order.content}</TableCell>
                <TableCell>{order.deliveryDate}</TableCell>
                <TableCell>{order.remark}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Container>
  );
};

export default OrderList;
